        return ADCS_E_NULL;

    if (adcs_vec3_normalize(b1, ADCS_EPS_NORM, &bn1) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(b2, ADCS_EPS_NORM, &bn2) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(r1, ADCS_EPS_NORM, &rn1) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(r2, ADCS_EPS_NORM, &rn2) != ADCS_OK)
        return ADCS_E_DEGENERATE;

    cb = adcs_vec3_cross(&bn1, &bn2);
    cr = adcs_vec3_cross(&rn1, &rn2);

    nb = adcs_vec3_norm(&cb);
    nr = adcs_vec3_norm(&cr);
    if (nb <= ADCS_EPS_COLLINEAR)
        return ADCS_E_DEGENERATE;
    if (nr <= ADCS_EPS_COLLINEAR)
        return ADCS_E_DEGENERATE;

